'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );


// VARIABLES //

// Excess kurtosis: (192 - 2π^4) / (π^4 - 16π^2 + 64):
var EXCESS_KURTOSIS = -0.8062497699541857;


// MAIN //

/**
* Returns the excess kurtosis for an anglit distribution with location parameter `mu` and scale parameter `sigma`.
*
* @param {number} mu - location parameter
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} excess kurtosis
*
* @example
* var y = kurtosis( 0.0, 1.0 );
* // returns ~-0.806
*
* @example
* var y = kurtosis( 2.0, 4.0 );
* // returns ~-0.806
*
* @example
* var y = kurtosis( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = kurtosis( 0.0, NaN );
* // returns NaN
*
* @example
* var y = kurtosis( 0.0, 0.0 );
* // returns NaN
*/
function kurtosis( mu, sigma ) {
	if (
		isnan( mu ) ||
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return NaN;
	}
	return EXCESS_KURTOSIS;
}


// EXPORTS //

module.exports = kurtosis;
